import{_ as a,c as t,o as e,a4 as o}from"./chunks/framework.BZPRC472.js";const m=JSON.parse('{"title":"郭永胜(Yanson)简历","description":"","frontmatter":{},"headers":[],"relativePath":"planTodo/pythonView.md","filePath":"planTodo/pythonView.md","lastUpdated":1783136725000}'),i={name:"planTodo/pythonView.md"},l=o('<h1 id="郭永胜-yanson-简历" tabindex="-1">郭永胜(Yanson)简历 <a class="header-anchor" href="#郭永胜-yanson-简历" aria-label="Permalink to &quot;郭永胜(Yanson)简历&quot;">​</a></h1><h2 id="基础信息" tabindex="-1">基础信息 <a class="header-anchor" href="#基础信息" aria-label="Permalink to &quot;基础信息&quot;">​</a></h2><ul><li>手机号：18626696269</li><li>邮箱：18626696269@163.com</li><li>所在地：上海</li><li>工作状态：在职</li></ul><h2 id="专业技能" tabindex="-1">专业技能 <a class="header-anchor" href="#专业技能" aria-label="Permalink to &quot;专业技能&quot;">​</a></h2><ol><li>熟练web开发</li><li>熟悉python开发</li><li>熟悉mysql, redis</li><li>熟悉使用flask, fastAPI</li><li>熟悉golang开发</li></ol><h2 id="项目经历" tabindex="-1">项目经历 <a class="header-anchor" href="#项目经历" aria-label="Permalink to &quot;项目经历&quot;">​</a></h2><h3 id="基于-rag-架构的智能知识库平台" tabindex="-1">基于 RAG 架构的智能知识库平台 <a class="header-anchor" href="#基于-rag-架构的智能知识库平台" aria-label="Permalink to &quot;基于 RAG 架构的智能知识库平台&quot;">​</a></h3><p><strong>任职</strong>：平台负责人，研发部 <strong>时间</strong>：2024年07月 - 2024年08月 <strong>技术栈</strong>：LangChain, Python, Streamlit, Vector DB (FAISS), OpenAI/Ollama</p><ul><li><strong>Situation（场景）</strong>：解决企业内部非结构化文档（PDF、Markdown、Docx）检索困难，以及大模型在回答特定业务问题时存在的“幻觉”挑战。</li><li><strong>Task（任务）</strong>：快速搭建一套具备私有知识挂载、语义检索及多轮对话能力的 AI 问答平台，并支持多种文档格式的一键上传与向量化处理。</li><li><strong>Action（行动）</strong><ol><li>核心链路：使用 LangChain 构建 RAG（检索增强生成）管道；利用 RecursiveCharacterTextSplitter 优化长文本切片，并结合 Embeddings 技术将数据持久化至向量数据库。</li><li>UI 开发：选用 Streamlit 快速实现响应式 Web 界面，集成文件上传组件、实时对话流（Chat UI）以及后台知识库管理功能。</li><li>性能优化：引入 ConversationBufferMemory 管理对话上下文；利用 Streamlit 的 session_state 维护多轮对话状态，确保逻辑连贯。</li><li>工程部署：基于 Docker 封装 Python 依赖环境，实现应用与向量数据库的解耦部署，确保跨环境运行的一致性。</li></ol></li><li><strong>Result（结果）</strong>：从 0 到 1 仅用 1 周即完成原型验证与上线；文档回答准确率提升至 85% 以上；显著降低了内部信息获取成本，成为团队日常业务查询的核心工具。</li></ul><h3 id="etl-系统开发" tabindex="-1">ETL 系统开发 <a class="header-anchor" href="#etl-系统开发" aria-label="Permalink to &quot;ETL 系统开发&quot;">​</a></h3><p><strong>任职</strong>：基础平台开发，研发部 <strong>技术栈</strong>：Python, Airflow, Docker</p><ul><li><strong>Action(行动)</strong>：运用 Apache Airflow 框架和 Docker 技术，快速搭建并部署了 ETL 系统。同时使用了 MySQL 作为指标数据库，并借助 Looker Studio 快速构建 BI 系统，保障数据分析便捷性。</li><li><strong>亮点</strong>：仅用三天时间就完成了从调研到项目部署的全部工作，使团队能够迅速进入 ETL 开发阶段，并节省了 50% 的开发时间。搭建完成的系统能够高效输出数据，为公司业务决策提供可靠的数据支撑。</li></ul><h3 id="基于测试自动化的多agent搭建平台" tabindex="-1">基于测试自动化的多agent搭建平台 <a class="header-anchor" href="#基于测试自动化的多agent搭建平台" aria-label="Permalink to &quot;基于测试自动化的多agent搭建平台&quot;">​</a></h3><p><strong>任职</strong>：系统架构工程师，研发部 <strong>技术栈</strong>：Python 3.13、LangGraph、LangChain、LLM/Agent 编排、Tool Calling、Playwright、Appium、Pydantic、Rich CLI</p><h4 id="架构设计" tabindex="-1">架构设计 <a class="header-anchor" href="#架构设计" aria-label="Permalink to &quot;架构设计&quot;">​</a></h4><p>设计并实现了基于 LangGraph 状态机的多 Agent 编排架构，设置单一入口 Router 开展意图识别，把用户自然语言请求分流至 design、code、test、swagger、ui、app、chat 共6条独立处理链路，做到一句话驱动全流程；抽象出统一的共享状态模型AgentState以及LLM Agent节点、ToolNode工具节点、纯状态辅助节点三类节点，拆分决策环节与执行环节，路由函数只读取状态、不再调用LLM，削减Token消耗，优化系统可测试性。</p><h4 id="核心链路实现" tabindex="-1">核心链路实现 <a class="header-anchor" href="#核心链路实现" aria-label="Permalink to &quot;核心链路实现&quot;">​</a></h4><ol><li>搭建代码生成链路自动修复闭环：由Architect拆分任务，Coder分步产出代码，Tester负责验收；验收判定失败时会回退交由Coder重做修复，借助fix_attempts参数将最大重试次数限定为3次，规避死循环问题。</li><li>设计4阶段顺序流转的design链路：产品方案&amp;架构设计 → 数据库DDL设计 → 后端服务代码编写 → 前端页面开发；借助designer_context节点提取API清单，压缩上下文体量，解决单次LLM输出过长被截断的问题，适配Boot、Gin等6种后端框架以及Vue3、React等4种前端框架。</li><li>搭建UI、App方向自动化测试链路：拆分Planner任务、Tester执行两大模块，依托Playwright适配二十余种浏览器操作、Appium实现移动端自动化，能够抓取网络请求、自动填写语义化表单、留存登录状态并且输出标准化测试报告。</li><li>落地Swagger/OpenAPI接口自动化测试流程，自动解析接口文档，批量产出pytest格式测试用例。</li></ol><h2 id="教育经历" tabindex="-1">教育经历 <a class="header-anchor" href="#教育经历" aria-label="Permalink to &quot;教育经历&quot;">​</a></h2><h3 id="湖南科技学院" tabindex="-1">湖南科技学院 <a class="header-anchor" href="#湖南科技学院" aria-label="Permalink to &quot;湖南科技学院&quot;">​</a></h3><p><strong>就读时段</strong>：2013年07月 – 2017年07月</p><ul><li>专业：通信工程（本科，计算机院，全日制）</li></ul><h2 id="荣誉奖项" tabindex="-1">荣誉奖项 <a class="header-anchor" href="#荣誉奖项" aria-label="Permalink to &quot;荣誉奖项&quot;">​</a></h2><ul><li>英语CET4级</li><li>软件设计师证书</li></ul>',24),r=[l];function n(s,h,d,c,g,u){return e(),t("div",null,r)}const _=a(i,[["render",n]]);export{m as __pageData,_ as default};
